/**
 * Admin templates for managing attendee statuses (owner-only settings page).
 *
 * The list, new, and delete pages are generated by
 * {@link defineAdminResourcePages}. The edit form is a panel in the attendee
 * status entity page. Its fields derive from the status field list.
 */

import type { AttendeeStatus } from "#db/attendee-statuses.ts";
import { t } from "#i18n";
import { Raw } from "#jsx/jsx-runtime.ts";
import { adminPath, adminPattern } from "#shared/admin-surface.ts";
import type { FormParams } from "#shared/form-data.ts";
import { entityToFieldValues } from "#shared/forms/values.ts";
import { ORDERED_LISTS } from "#shared/ordered-lists.ts";
import { STATUS_FIELDS } from "#shared/records/status-fields.ts";
import { statusRecord } from "#shared/records/statuses.ts";
import type { TableColumn } from "#shared/tables/column.ts";
import { recordEditPanel } from "#templates/admin/admin-page.tsx";
import { ConfirmPage } from "#templates/admin/confirm-page.tsx";
import {
  defineRecordPages,
  pageLabels,
  writableNameColumn,
} from "#templates/admin/resource-pages.tsx";
import { ActionButton, GuideFooter } from "#templates/components/actions.tsx";
import { Badge } from "#templates/components/badge.tsx";
import { ProseIntro } from "#templates/components/prose-heading.tsx";
import { idOptions, SelectField } from "#templates/components/select-field.tsx";
import { translatedTableColumn } from "#templates/components/translated-table-column.ts";
import { fieldsForm } from "#templates/fields/record-fields.ts";
import type { AdminSession } from "#types";

const LIST_PATH = adminPattern("statuses");

/** Render one row's flag badges. */
const statusBadges = (s: AttendeeStatus): JSX.Element => (
  <>
    {s.isPublicDefault && <Badge>{t("statuses.badge_public_default")}</Badge>}
    {s.isPaidDefault && <Badge>{t("statuses.badge_paid")}</Badge>}
    {s.isReservation && (
      <Badge>
        {t("statuses.badge_reservation", { amount: s.reservationAmount })}
      </Badge>
    )}
  </>
);

/** The attendee-status data columns; ordering controls are added by the shared
 * table renderer. */
const statusColumns: TableColumn<AttendeeStatus>[] = [
  writableNameColumn(
    (s) => adminPath("status", { id: s.id }),
    (s) => s.name,
  ),
  translatedTableColumn("flags", "statuses.flags_header", (s) =>
    statusBadges(s),
  ),
];

/** The per-request status form, derived from the status field list. */
export const getStatusForm = fieldsForm(STATUS_FIELDS);

/** The values the status form draws: the stored row, or the values an edit
 *  sent before its refusal. */
const statusFormValues = (
  status: AttendeeStatus | undefined,
  values?: FormParams,
): Record<string, string | number | null> =>
  values === undefined
    ? entityToFieldValues(status, getStatusForm().fields, {})
    : values.toRenderValues();

/** The form boxes of the status fields. */
const statusFields = (
  status: AttendeeStatus | undefined,
  values?: FormParams,
): JSX.Element => (
  <Raw html={getStatusForm().render(statusFormValues(status, values))} />
);

/** The status page labels. The stock status pages and the retire page both read
 *  them, so one vocabulary names both. */
const STATUS_LABELS = pageLabels("statuses");

/** What the delete page offers beneath the heading: the reassign choice for a
 *  status attendees hold (the count and the statuses they can move to), the
 *  prerequisite the save will refuse on for a default or last status — said
 *  above a confirmation the save will still refuse if submitted — and null
 *  for a delete that proceeds as it stands. The route decides through the
 *  same predicate the delete command refuses by. */
export type StatusRetire =
  | { blocked: string }
  | { count: number; others: readonly AttendeeStatus[] };

/** The status delete page: the usual type-the-name confirmation, plus — when
 *  attendees hold this status — the count, a warning, and a required picker
 *  of the statuses they can move to, or the prerequisite the save would
 *  refuse on, above a confirmation the save still refuses if submitted. The
 *  picker posts `reassignStatusId`, which the delete command reads inside
 *  its transaction. */
export const retireStatusDeletePage = (
  status: AttendeeStatus,
  retire: StatusRetire | null,
  session: AdminSession,
  error?: string,
): string => {
  const choice = retire !== null && "count" in retire ? retire : undefined;
  const blocked = retire !== null && "blocked" in retire ? retire : undefined;
  return ConfirmPage({
    action: `/admin/settings/statuses/${status.id}/delete`,
    active: LIST_PATH,
    buttonText: STATUS_LABELS.deleteButton,
    confirm: {
      args: { name: status.name },
      key: "statuses.delete_confirm",
    },
    danger: false,
    error,
    heading: STATUS_LABELS.deleteTitle,
    label: t("common.name"),
    name: status.name,
    session,
    title: STATUS_LABELS.deleteTitle,
    ...(choice !== undefined
      ? {
          children: (
            <label>
              {t("statuses.delete_reassign_label")}
              <SelectField
                name="reassignStatusId"
                options={[
                  { label: t("statuses.delete_reassign_prompt"), value: "" },
                  ...idOptions(choice.others, (other) => other.name),
                ]}
                required
                value=""
              />
            </label>
          ),
          prompt: {
            args: { count: choice.count },
            key: "statuses.delete_in_use",
          },
          warning: <p>{t("statuses.delete_reassign_warning")}</p>,
        }
      : {}),
    ...(blocked !== undefined ? { children: <p>{blocked.blocked}</p> } : {}),
  });
};

/** The entity page's Edit tab, including rejected submitted values. */
export const AttendeeStatusEditPanel = ({
  status,
  error,
  values,
}: {
  status: AttendeeStatus;
  error?: string;
  values?: FormParams;
}): JSX.Element =>
  recordEditPanel("statusEdit", t("statuses.form_save_button"))(
    status.id,
    error,
    statusFields(status, values),
  );

const deleteChildren = (status: AttendeeStatus): JSX.Element => (
  <p>{t("statuses.delete_confirm", { name: status.name })}</p>
);

export const statusPages = defineRecordPages(statusRecord, {
  delete: {
    children: deleteChildren,
    danger: false,
    label: t("common.name"),
    name: (status) => status.name,
  },
  labels: STATUS_LABELS,
  list: {
    actions: (
      <ActionButton href={adminPattern("statusNew")} icon="plus">
        {t("statuses.add_status_button")}
      </ActionButton>
    ),
    columns: statusColumns,
    guideFooter: (
      <GuideFooter href={`${adminPattern("guide")}#attendee-statuses`}>
        {t("statuses.guide_link")}
      </GuideFooter>
    ),
    intro: <ProseIntro html={t("statuses.attendee_statuses_description")} />,
    reorder: ORDERED_LISTS.status.column(),
  },
  renderFields: statusFields,
});
